// Everything on the shelves. Edit this file to shelve your own setup.
//
// Shelf: name, color (spine color), glyph (emblem), books.
// Book fields (only n, k, b and w are required):
//   n    name                    k    kind label
//   t    tags                    b    one-line blurb
//   w    what it does            how  how it works (list)
//   u    when to reach for it    ex   example prompts or commands (list)
//   tip  one practical tip       s    source link
//   off  installed but switched off
//   get  { cmd, note, file, link }  install command to copy, a note under it,
//        a file in this repo to download, or a page to open

export const REPO = 'Arin117Kaushik/claude-library';
const RAW = `https://raw.githubusercontent.com/${REPO}/main/`;
const agent = (file) => ({
  cmd: `mkdir -p ~/.claude/agents && curl -fsSL ${RAW}kit/agents/${file} -o ~/.claude/agents/${file}`,
  note: 'macOS, Linux or Git Bash. Restart Claude Code, then name the agent in a prompt.',
  file: `kit/agents/${file}`,
});
const skill = (name) => ({
  cmd: `npx degit ${REPO}/kit/skills/${name} ~/.claude/skills/${name}`,
  note: 'Copies the skill folder into your global skills. Start a new session to load it.',
  link: `https://github.com/${REPO}/tree/main/kit/skills/${name}`,
});
const plugin = (repo, id) => ({
  cmd: `claude plugin marketplace add ${repo} && claude plugin install ${id}`,
  note: 'Run in a terminal, or use the same words as /plugin commands inside Claude Code.',
});
const antislop = { cmd: 'npx antislop-ai', note: 'The installer asks which agents to install for. Pick the skills you want.' };
const superpowers = plugin('obra/superpowers-marketplace', 'superpowers@superpowers-marketplace');
const winget = (id, link) => ({ cmd: `winget install ${id}`, note: 'Windows. On macOS use Homebrew, on Linux your package manager.', link });
const pip = (pkgs) => ({ cmd: `python -m pip install ${pkgs}`, note: 'Any Python 3.10 or newer.' });
const connector = { note: 'Add it in Claude: Settings, then Connectors. It works in claude.ai, the desktop app and Claude Code.', link: 'https://claude.ai/settings/connectors' };

